	["皇家历史学家阿克瑟努斯"] = { "I am ready, Historian Archesonus.", "Interesting, continue please.", "Of course I will help!", "That is tragic. How did this happen?", "Unbelievable! How dare they??" },
	["皮尔斯·沙克尔顿"] = { "I am interested in mage training.", "I wish to unlearn my talents.", "Learn about Dual Talent Specialization.", "Purchase a Dual Talent Specialization.", "Yes. I do." },
